import { rm } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import react from '@vitejs/plugin-react';
import { defineConfig, type Plugin } from 'vitest/config';

/**
 * `public/mockServiceWorker.js` (generated by `msw init`) only serves the dev mock API. Vite
 * copies everything in `public/` to `dist/`, so drop it from production output; the
 * `./mocks` code itself is already excluded by the `import.meta.env.DEV` gate in main.tsx.
 */
function stripMockServiceWorker(): Plugin {
  let outDir = 'dist';
  return {
    name: 'acme:strip-mock-service-worker',
    apply: 'build',
    configResolved(config) {
      outDir = join(config.root, config.build.outDir);
    },
    async closeBundle() {
      await rm(join(outDir, 'mockServiceWorker.js'), { force: true });
    },
  };
}

export default defineConfig({
  plugins: [react(), stripMockServiceWorker()],
  resolve: {
    alias: {
      '@acme/shared': fileURLToPath(new URL('../../packages/shared/src/index.ts', import.meta.url)),
    },
  },
  server: {
    port: 5173,
    proxy: { '/api': 'http://localhost:3000' },
  },
  test: {
    name: 'web',
    environment: 'jsdom',
    setupFiles: ['./src/test/setup.ts'],
  },
});
